int f(int x__in, int y__in){
int y = y__in;
int x = x__in;
int tmp = 0;
int xtmp = 0;
while (y != 0)
{
  tmp = y;
  xtmp = x;
  if ((x <= 0) || (y <= 0))
  {
    y = 0;
  }
  else
  {
    if (x == y)
    {
      y = 0;
    }
    else
    {
      while (xtmp > y)
      {
        xtmp = xtmp - y;
      }

    }
  }
  y = xtmp;
  x = tmp;
}

return 0;
}
